import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;
  const group = new Group();

  // 1. STAGE BACKDROP (Engineered vertical gradient)
  // Dimensions roughly ~7x6 units behind the node to ensure no flat void
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();

  const inkColor = new Color('#16161d');
  const surfaceColor = new Color('#0b0b10');

  bgMat.colorNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uv().y
  );

  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -0.5);
  group.add(backdrop);

  // 2. HERO FEATURE PLANE (A textured card exhibiting the image)
  const cardGeo = new PlaneGeometry(3.2, 2.0);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.15,
    transparent: true,
    opacity: 0.95
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, -0.4, 0.1);
  group.add(cardMesh);

  // 3. TEXT CONTENT (Branded "Collection" display title)
  // Retrieve copy safely using visualSpec fallback path
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline' || item.text === 'Collection');
  const rawText = textItem ? textItem.text : 'Collection';

  // Render text content using specified mono/serif bounds
  const titleText = ctx.fontAtlas.createText(rawText, {
    fontSize: 54, // Proportional headline size scale
    color: '#e8ecf2', // Brand paper color for high contrast
    align: 'center'
  });

  // Placed elegantly above the featured image
  titleText.position.set(0, 0.9, 0.25);
  group.add(titleText);

  // 4. ENGINEERED LOCAL LIGHTING (Rim / Accent accentuation)
  const rimLight = new DirectionalLight('#ff2a38', 0.6); // Accent red rim
  rimLight.position.set(-2, 3, 2);
  group.add(rimLight);

  const fillLight = new DirectionalLight('#e8ecf2', 0.4); // Paper fill light
  fillLight.position.set(3, -2, 1);
  group.add(fillLight);

  // 5. STATIC COMPOSITION ENTRANCE
  gsap.fromTo(cardMesh.position, 
    { y: -0.6, z: -0.1 }, 
    { y: -0.4, z: 0.1, duration: 0.9, ease: 'power3.out' }
  );
  gsap.fromTo(titleText.position, 
    { y: 0.7 }, 
    { y: 0.9, duration: 0.8, ease: 'power2.out', delay: 0.05 }
  );

  // Apply optional primitive attachments
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const instance = ctx.primitives[prim.name](group, prim.params);
        activePrimitives.push(instance);
      }
    });
  }

  // Graceful cleanup interface
  group.userData = {
    cleanup() {
      activePrimitives.forEach(p => p?.cleanup?.());
      bgGeo.dispose();
      bgMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
    }
  };

  return group;
}
